
DROP TABLE IF EXISTS emprestimo, leitor, cidade, pais, obra_autor, autor, obra_area, obra, area, idioma CASCADE; -- Elimina a tabela

CREATE TABLE tb_alunos (
    id_aluno INT GENERATED ALWAYS AS IDENTITY, -- O GENERATED ALWAYS AS IDENTITY, significa que o banco sempre vai 
                                               -- criar o número e não vai permitir que você insira um valor manualmente.
    nome VARCHAR(100)
);

-- O GENERATED BY DEFAULT AS IDENTITY -> . O banco gera o número sozinho se você não mandar nada, mas se você resolver 
-- forçar um número manualmente no INSERT, ele aceita e grava o seu número.

